application.css:
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Space+Grotesk:wght@500;600;700&display=swap');

:root { color-scheme: light; --ink: #202331; --muted: #85899b; --purple: #7157e8; --purple-dark: #5a43c9; --line: #ececf3; --card: #fff; }
* { box-sizing: border-box; }
body { margin: 0; min-height: 100vh; font-family: 'DM Sans', sans-serif; color: var(--ink); background: #f6f5fb; background-image: radial-gradient(circle at 10% 10%, #e9e2ff 0, transparent 28%), radial-gradient(circle at 90% 85%, #dff4f1 0, transparent 25%); }
.app-shell { min-height: 100vh; display: grid; place-items: center; padding: 32px 18px; }
.todo-card { width: min(100%, 590px); background: var(--card); border: 1px solid rgba(255,255,255,.8); border-radius: 25px; padding: 39px 40px 23px; box-shadow: 0 22px 60px rgba(60, 48, 116, .13); }
.app-header { display: flex; align-items: center; gap: 17px; margin-bottom: 31px; }
.brand-mark { width: 49px; height: 49px; display: grid; place-items: center; border-radius: 15px; color: white; font-size: 26px; font-weight: 700; background: linear-gradient(135deg, #8870f4, #6248d3); box-shadow: 0 8px 16px #755be83b; }
.eyebrow { margin: 0 0 3px; color: var(--purple); font-size: 10px; letter-spacing: 1.5px; font-weight: 700; }
h1, h2, h3 { font-family: 'Space Grotesk', sans-serif; } h1 { margin: 0; font-size: 29px; letter-spacing: -.8px; } .subtitle { margin: 3px 0 0; color: var(--muted); font-size: 13px; }
.task-form { display: flex; gap: 10px; margin-bottom: 34px; } input { min-width: 0; flex: 1; border: 1px solid #e4e4ed; border-radius: 12px; background: #fafafd; padding: 14px 15px; outline: none; color: var(--ink); font: inherit; transition: .2s; } input::placeholder { color: #afb1bd; } input:focus { border-color: var(--purple); box-shadow: 0 0 0 4px #7157e81a; background: #fff; }
button { font: inherit; cursor: pointer; border: 0; } .task-form button { padding: 0 17px; border-radius: 12px; color: white; background: var(--purple); font-weight: 700; transition: .2s; } .task-form button:hover { background: var(--purple-dark); transform: translateY(-1px); } .task-form button span { font-size: 18px; vertical-align: -1px; margin-left: 4px; }
.list-heading { display: flex; align-items: center; justify-content: space-between; margin-bottom: 13px; } h2 { margin: 0; font-size: 17px; } .count-pill { color: var(--purple); background: #f0edff; border-radius: 30px; padding: 6px 11px; font-size: 12px; font-weight: 700; } .count-label { color: #897dcc; font-weight: 500; }
.task-list { display: grid; gap: 9px; } .task { display: flex; align-items: center; gap: 12px; min-height: 57px; padding: 9px 11px 9px 14px; border: 1px solid var(--line); border-radius: 13px; background: #fff; animation: appear .25s ease-out; } @keyframes appear { from { opacity: 0; transform: translateY(-5px); } to { opacity: 1; transform: none; } }
.complete-control { width: 22px; height: 22px; flex: 0 0 22px; border: 2px solid #c9c9d8; border-radius: 7px; background: white; color: white; display: grid; place-items: center; font-size: 14px; transition: .2s; } .complete-control:hover { border-color: var(--purple); } .task[data-completed="true"] .complete-control { border-color: var(--purple); background: var(--purple); } .task-text { flex: 1; min-width: 0; overflow-wrap: anywhere; font-size: 14px; line-height: 1.4; } .task[data-completed="true"] .task-text { color: #a2a3ae; text-decoration: line-through; }
.delete-control { width: 30px; height: 30px; border-radius: 8px; color: #b8b9c4; background: transparent; font-size: 19px; line-height: 1; } .delete-control:hover { color: #e35d75; background: #fff0f2; }
.empty-state { text-align: center; padding: 38px 10px 35px; color: var(--muted); } .empty-icon { margin: auto; width: 42px; height: 42px; display: grid; place-items: center; border-radius: 50%; color: #8069e9; background: #f1efff; font-size: 19px; } .empty-state h3 { margin: 13px 0 4px; font-size: 15px; } .empty-state p { margin: 0; font-size: 13px; } .app-footer { border-top: 1px solid var(--line); margin-top: 18px; padding-top: 19px; color: #aaaab7; text-align: center; font-size: 11px; } .status-dot { display: inline-block; width: 6px; height: 6px; margin-right: 5px; border-radius: 50%; background: #62c9a2; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
@media (max-width: 480px) { .todo-card { padding: 29px 20px 20px; border-radius: 20px; } .task-form { flex-direction: column; } .task-form button { min-height: 46px; } }

application.javascript:
const form = document.getElementById('task-form');
const input = document.querySelector('[data-testid="task-input"]');
const list = document.querySelector('[data-testid="task-list"]');
const emptyState = document.getElementById('empty-state');
const count = document.querySelector('[data-testid="incomplete-count"]');
let tasks = [];

function render() {
  list.innerHTML = '';
  tasks.forEach(task => {
    const item = document.createElement('div');
    item.className = 'task';
    item.dataset.testid = 'task';
    item.dataset.completed = String(task.completed);

    const toggle = document.createElement('button');
    toggle.type = 'button';
    toggle.className = 'complete-control';
    toggle.dataset.testid = 'task-complete';
    toggle.setAttribute('aria-label', task.completed ? 'Mark task incomplete' : 'Mark task complete');
    toggle.setAttribute('aria-pressed', String(task.completed));
    toggle.textContent = task.completed ? '✓' : '';
    toggle.addEventListener('click', () => {
      task.completed = !task.completed;
      render();
    });

    const text = document.createElement('span');
    text.className = 'task-text';
    text.dataset.testid = 'task-text';
    text.textContent = task.text;

    const remove = document.createElement('button');
    remove.type = 'button';
    remove.className = 'delete-control';
    remove.dataset.testid = 'task-delete';
    remove.setAttribute('aria-label', `Delete task: ${task.text}`);
    remove.textContent = '×';
    remove.addEventListener('click', () => {
      tasks = tasks.filter(entry => entry.id !== task.id);
      render();
    });

    item.append(toggle, text, remove);
    list.appendChild(item);
  });
  const remaining = tasks.filter(task => !task.completed).length;
  count.textContent = remaining;
  emptyState.hidden = tasks.length > 0;
}

form.addEventListener('submit', event => {
  event.preventDefault();
  const text = input.value.trim();
  if (!text) {
    input.focus();
    return;
  }
  tasks.push({ id: Date.now() + Math.random(), text, completed: false });
  input.value = '';
  render();
  input.focus();
});

render();
